### Contoh

`Required` berguna setelah semua kolom opsional dilengkapi dengan nilai bawaan:

```ts
type Opsi = { batas?: number; urut?: "baru" | "lama" };
const BAWAAN: Required<Opsi> = { batas: 10, urut: "baru" };

function cari(opsi: Opsi = {}) {
  const o: Required<Opsi> = { ...BAWAAN, ...opsi };
  return `${o.batas} ${o.urut}`; // tidak perlu cek undefined lagi
}
```

`Readonly` hanya **dangkal** (satu tingkat):

```ts
const p: Readonly<{ alamat: { kota: string } }> = { alamat: { kota: "Bandung" } };
p.alamat = { kota: "Jakarta" }; // error TS2540
p.alamat.kota = "Jakarta";      // lolos: tingkat dalam tidak ikut terkunci
```

