type Profil = { nama: string; email: string; kota?: string };
function ubahProfil(lama: Profil, perubahan: Partial<Profil>): Profil {
  return { ...lama, ...perubahan };
}
const awal: Readonly<Profil> = { nama: "Rina", email: "rina@contoh.id" };
const baru = ubahProfil(awal, { kota: "Bandung" });
const baru2 = ubahProfil(baru, { email: "rina.p@contoh.id" });
console.log(awal.kota ?? "-", baru.kota);
console.log(baru2.nama, baru2.email, baru2.kota);

