cards.solution:
type Pengaturan = { tema: string; bahasa: string; notifikasi: boolean };
const BAWAAN: Readonly<Pengaturan> = { tema: "terang", bahasa: "id", notifikasi: true };
function gabung(ubah: Partial<Pengaturan>): Pengaturan {
  return { ...BAWAAN, ...ubah };
}
const p = gabung({ tema: "gelap" });
console.log(p.tema, p.bahasa, p.notifikasi);
